/**
 * Supported currencies for item listings and bidder display.
 * @trace DSN-012 REQ-001 REQ-005
 */
export enum Currency { CHF = 'CHF', EUR = 'EUR', USD = 'USD' }

/**
 * Lifecycle state of an item auction.
 * @trace DSN-013 REQ-001 REQ-004
 */
export enum AuctionStatus {
  open = 'open',
  closed = 'closed',
  unsold = 'unsold',
}

/**
 * A user identified by a unique display name, with no password.
 * @trace DSN-014 REQ-008
 */
export class User {
  constructor(public id: string, public displayName: string) {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('User id must be a non-empty string');
    }
    this.displayName = User.validateDisplayName(displayName);
  }

  /** Checks that a display name has 2 to 20 characters and returns it trimmed; throws on invalid input. */
  private static validateDisplayName(name: string): string {
    const trimmed = typeof name === 'string' ? name.trim() : '';
    if (trimmed.length < 2 || trimmed.length > 20) {
      throw new Error('Display name must be between 2 and 20 characters');
    }
    return trimmed;
  }
}

