import { Item } from './Item.js';
import { ItemView } from './ItemView.js';
import { ItemService } from './ItemService.js';
import { Currency } from './Currency.js';

/**
 * HTTP routes for items: listing, viewing one item, and listing open items.
 *
 * @trace DSN-019 REQ-001 REQ-005 REQ-004
 */
export class ItemController {
  constructor(private readonly itemService: ItemService) {}

  /** Validates a listing and creates an open auction; throws on missing fields or an unsupported currency. */
  async listItem(userId: string, title: string, startingPrice: number, endTime: string, currency: string): Promise<Item> {
    if (!userId) throw new Error('Seller id is required');
    if (!title) throw new Error('Title is required');
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice)) {
      throw new Error('Starting price is required');
    }
    if (!endTime) throw new Error('End time is required');
    if (!currency) throw new Error('Currency is required');
    if (!this.isCurrency(currency)) throw new Error(`Unsupported currency ${currency}`);
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) throw new Error('End time is invalid');
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /** Returns one item with its display-currency view; throws if the item is not found or the display currency is unsupported. */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    if (displayCurrency !== undefined && !this.isCurrency(displayCurrency)) {
      throw new Error(`Unsupported display currency ${displayCurrency}`);
    }
    const item = await this.itemService.getItem(id);
    return {
      item,
      displayCurrency: displayCurrency === undefined ? null : (displayCurrency as Currency),
      convertedStartingPrice: null,
      convertedHighestBid: null,
    };
  }

  /** Returns all auctions that are currently open for bids. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }

  /** Tells whether a value is one of the supported currencies. */
  private isCurrency(value: string): value is Currency {
    return (Object.values(Currency) as string[]).includes(value);
  }
}

import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 *
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  constructor(private readonly itemService: ItemService, public intervalMs: number) {}

  /** Closes every auction whose end time is at or before now; propagates errors from ItemService. */
  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

/**
 * Creates and reads items, closes due auctions.
 *
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly userStore: UserStore,
    private readonly auctionEventPublisher: AuctionEventPublisher,
  ) {}

  /** Validates and stores a new open item; throws Error on invalid input. */
  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    if (!sellerId || sellerId.trim() === '') {
      throw new Error('Seller id is required');
    }
    if (!title || title.trim() === '') {
      throw new Error('Title is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('Starting price must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('End time is required and must be a valid date');
    }
    if (!(Object.values(Currency) as string[]).includes(currency)) {
      throw new Error(`Currency must be one of ${Object.values(Currency).join(', ')}`);
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  /** Returns the item with the given id; throws Error ending in not found when missing. */
  async getItem(id: string): Promise<Item> {
    const item = await this.itemStore.findItem(id);
    if (!item) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  /** Returns all items that are currently open for bids. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  /** Closes every open item whose end time has been reached, sets winner or unsold, and publishes the closing. */
  async closeDueAuctions(now: Date): Promise<void> {
    const due = await this.itemStore.findDueItems(now);
    for (const item of due) {
      if (item.status !== AuctionStatus.open || item.isOpen(now)) {
        continue;
      }
      if (item.highestBidderId === null) {
        item.status = AuctionStatus.unsold;
        item.winnerId = null;
      } else {
        item.status = AuctionStatus.closed;
        item.winnerId = item.highestBidderId;
      }
      await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(item);
    }
  }
}

import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using rates cached for a configurable time; returns null when unavailable.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an amount between display currencies, returning null when no rate is available; throws on invalid amount or currency. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error(`Invalid amount ${amount}`);
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`Unsupported currency ${from}`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`Unsupported currency ${to}`);
    }
    if (from === to) {
      return amount;
    }
    const rates = await this.getRates(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number' || !Number.isFinite(rate)) {
      return null;
    }
    return amount * rate;
  }

  /** Returns cached rates for the base currency, fetching fresh ones when the cache is older than the TTL; returns null when unavailable. */
  private async getRates(base: Currency): Promise<Record<string, number> | null> {
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: now });
      return rates;
    } catch {
      return null;
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';
import { UserStore } from './UserStore.js';

const LATE_BID_WINDOW_MS = 2 * 60 * 1000;
const MIN_INCREMENT = 1;

/**
 * Validates and stores bids, extends end time, and publishes accepted bids to the event feed.
 *
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Validates a bid on an open item, stores it, extends a late auction and publishes it; throws if the item is not found or the bid is invalid. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new Error('Bid amount must be a positive number');
    }
    const item = await this.itemStore.findItem(itemId);
    if (!item) {
      throw new Error(`Item ${itemId} not found`);
    }
    const now = new Date();
    const endTime = new Date(item.endTime);
    if (now.getTime() >= endTime.getTime()) {
      throw new Error('Auction has ended');
    }
    if (bidderId === item.sellerId) {
      throw new Error('Seller cannot bid on own item');
    }
    const highest = item.highestBid ?? null;
    if (highest === null) {
      if (amount < item.startingPrice) {
        throw new Error(`First bid must be at least the starting price ${item.startingPrice}`);
      }
    } else if (amount < highest + MIN_INCREMENT) {
      throw new Error(`Bid must be at least ${MIN_INCREMENT} higher than the current highest bid ${highest}`);
    }

    const bid = new Bid(randomUUID(), item.id, bidderId, amount, now);
    await this.itemStore.saveBid(bid);

    item.highestBid = amount;
    if (endTime.getTime() - now.getTime() <= LATE_BID_WINDOW_MS) {
      item.endTime = new Date(endTime.getTime() + LATE_BID_WINDOW_MS);
    }
    await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(bid, item);
    return bid;
  }
}

import { Currency } from '../auction-api/Currency.js';

const API_URL = 'https://api.frankfurter.app/latest';
const CACHE_TTL_MS = 60 * 60 * 1000;

interface CacheEntry {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Fetches display exchange rates from the Frankfurter API with a one hour cache.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private readonly cache = new Map<string, CacheEntry>();

  constructor() {}

  /** Returns rates for the base currency, using the cache for one hour; returns an empty record when the API is unreachable and no cached rate is valid. Throws if the base currency is unsupported. */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    if (!Object.values(Currency).includes(base)) {
      throw new Error(`Unsupported currency ${String(base)}`);
    }
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
      return { ...cached.rates };
    }
    try {
      const rates = await this.request(base);
      this.cache.set(base, { rates, fetchedAt: Date.now() });
      return { ...rates };
    } catch {
      if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
        return { ...cached.rates };
      }
      return {};
    }
  }

  /** Performs the HTTPS request and returns the rate map; throws on network or response errors. */
  private async request(base: Currency): Promise<Record<string, number>> {
    const url = `${API_URL}?from=${base}&to=${Object.values(Currency).join(',')}`;
    const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
    if (!response.ok) {
      throw new Error(`Frankfurter responded with status ${response.status}`);
    }
    const body = (await response.json()) as { rates?: Record<string, unknown> };
    if (!body.rates || typeof body.rates !== 'object') {
      throw new Error('Frankfurter response has no rates');
    }
    const rates: Record<string, number> = {};
    for (const [code, value] of Object.entries(body.rates)) {
      if (typeof value === 'number') {
        rates[code] = value;
      }
    }
    return rates;
  }
}

