/**
 * Persists items and bids in the API server's SQLite database.
 *
 * @trace DSN-029 REQ-001 REQ-002 REQ-004
 */
export class ItemStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS items (
        id TEXT PRIMARY KEY,
        sellerId TEXT NOT NULL,
        title TEXT NOT NULL,
        startingPrice REAL NOT NULL,
        currency TEXT NOT NULL,
        endTime TEXT NOT NULL,
        status TEXT NOT NULL,
        highestBidAmount REAL,
        highestBidderId TEXT,
        winnerId TEXT
      )
    `);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS bids (
        id TEXT PRIMARY KEY,
        itemId TEXT NOT NULL,
        bidderId TEXT NOT NULL,
        amount REAL NOT NULL,
        placedAt TEXT NOT NULL
      )
    `);
  }

  /** Inserts a new item or updates the stored item with the same id; throws if the currency is not CHF, EUR or USD. */
  async saveItem(item: Item): Promise<Item> {
    if (!(Object.values(Currency) as string[]).includes(item.currency)) {
      throw new Error(`Currency ${item.currency} is not supported`);
    }
    const exists = this.db.prepare('SELECT id FROM items WHERE id = ?').get(item.id) !== undefined;
    if (exists) {
      this.db
        .prepare(
          'UPDATE items SET sellerId = ?, title = ?, startingPrice = ?, currency = ?, endTime = ?, status = ?, highestBidAmount = ?, highestBidderId = ?, winnerId = ? WHERE id = ?',
        )
        .run(
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
          item.id,
        );
    } else {
      this.db
        .prepare(
          'INSERT INTO items (id, sellerId, title, startingPrice, currency, endTime, status, highestBidAmount, highestBidderId, winnerId) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        )
        .run(
          item.id,
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
        );
    }
    return item;
  }

  /** Returns the item with the given id, or null if none is stored. */
  async findItem(id: string): Promise<Item | null> {
    const row = this.db.prepare('SELECT * FROM items WHERE id = ?').get(id);
    if (row === undefined) {
      return null;
    }
    return this.toItem(row as unknown as ItemRow);
  }

  /** Returns all items whose status is open. */
  async findOpenItems(): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ?')
      .all(AuctionStatus.open) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Returns all open items whose end time is at or before the given instant. */
  async findDueItems(now: Date): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ? AND endTime <= ?')
      .all(AuctionStatus.open, now.toISOString()) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Inserts a new bid or updates the stored bid with the same id; throws if the amount is not a positive number. */
  async saveBid(bid: Bid): Promise<Bid> {
    if (!Number.isFinite(bid.amount) || bid.amount <= 0) {
      throw new Error('Bid amount must be a positive number');
    }
    const exists = this.db.prepare('SELECT id FROM bids WHERE id = ?').get(bid.id) !== undefined;
    if (exists) {
      this.db
        .prepare('UPDATE bids SET itemId = ?, bidderId = ?, amount = ?, placedAt = ? WHERE id = ?')
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString(), bid.id);
    } else {
      this.db
        .prepare('INSERT INTO bids (id, itemId, bidderId, amount, placedAt) VALUES (?, ?, ?, ?, ?)')
        .run(bid.id, bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString());
    }
    return bid;
  }

  private toItem(row: ItemRow): Item {
    return new Item(
      row.id,
      row.sellerId,
      row.title,
      row.startingPrice,
      row.currency as Currency,
      new Date(row.endTime),
      row.status as AuctionStatus,
      row.highestBidAmount,
      row.highestBidderId,
      row.winnerId,
    );
  }
}

/**
 * WebSocket gateway for browsers that keeps watchers per item and broadcasts only to them.
 *
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private readonly outbox: Map<string, string[]> = new Map();

  constructor(public watchers: Map<string, Set<string>>) {}

  /** Registers a client as a watcher of an item; throws if either id is empty. */
  watch(clientId: string, itemId: string): void {
    if (!clientId || !itemId) {
      throw new Error('clientId and itemId are required');
    }
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set<string>();
      this.watchers.set(itemId, clients);
    }
    clients.add(clientId);
  }

  /** Removes a client from an item's watchers; drops the item when no watcher remains. */
  unwatch(clientId: string, itemId: string): void {
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    clients.delete(clientId);
    if (clients.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Queues a message for every client watching the item only; throws if the message is empty. */
  broadcast(itemId: string, message: string): void {
    if (!message) {
      throw new Error('message is required');
    }
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    for (const clientId of clients) {
      const queue = this.outbox.get(clientId) ?? [];
      queue.push(message);
      this.outbox.set(clientId, queue);
    }
  }
}

import { WebSocket, WebSocketServer } from 'ws';

/**
 * Internal ws endpoint on the API server that relays every published event to all connected live server instances.
 *
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  private readonly server: WebSocketServer;
  private readonly clients: Set<WebSocket> = new Set();

  constructor() {
    const port = Number(process.env.EVENT_FEED_PORT ?? 8081);
    this.server = new WebSocketServer({ port });
    this.server.on('connection', (socket: WebSocket) => {
      this.clients.add(socket);
      socket.on('close', () => this.clients.delete(socket));
      socket.on('error', () => this.clients.delete(socket));
    });
  }

  /** Sends the topic and payload to every connected instance; throws if the topic is empty. */
  publish(topic: string, payload: string): void {
    if (topic.trim() === '') {
      throw new Error('Topic must not be empty');
    }
    const message = JSON.stringify({ topic, payload });
    for (const socket of this.clients) {
      if (socket.readyState === WebSocket.OPEN) {
        socket.send(message);
      }
    }
  }
}

