    this.sellerId = sellerId;
    this.title = title;
    this.startingPrice = startingPrice;
    this.currency = currency;
    this.endTime = endTime;
    this.status = status;
    this.highestBidAmount = highestBidAmount;
    this.highestBidderId = highestBidderId;
    this.winnerId = winnerId;
  }

  /** Returns true when the status is open and the end time has not been reached at now. */
  isOpen(now: Date): boolean {
    return this.status === AuctionStatus.open && now.getTime() < this.endTime.getTime();
  }

  /** Returns the lowest amount a new bid must reach: the starting price, or one unit above the highest bid. */
  minimumBid(): number {
    return this.highestBidAmount === null ? this.startingPrice : this.highestBidAmount + 1;
  }

  /** Moves the end time 2 minutes later when now is within the last 2 minutes of an open auction; returns whether it did. */
  extendIfLate(now: Date): boolean {
    if (!this.isOpen(now)) {
      return false;
    }
    const remaining = this.endTime.getTime() - now.getTime();
    if (remaining > LATE_WINDOW_MS) {
      return false;
    }
    this.endTime = new Date(this.endTime.getTime() + LATE_WINDOW_MS);
    return true;
  }
}
