 * Client of the API server's internal event feed that forwards each incoming event to the live gateway.
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventFeedClient {
  private readonly gateway: LiveGateway = new LiveGateway(new Map<string, Set<string>>());
  private socket: WebSocket | null = null;
  private readonly retryMs: number = 1000;

  constructor(public apiUrl: string) {}

  /** Opens the event feed websocket to apiUrl and reconnects after it closes; throws if apiUrl is empty. */
  connect(): void {
    if (!this.apiUrl) {
      throw new Error('API URL is required');
    }
    const socket = new WebSocket(this.apiUrl);
    this.socket = socket;
    socket.on('message', (data: Buffer | string) => {
      let event: { topic?: unknown; payload?: unknown };
      try {
        event = JSON.parse(data.toString());
      } catch {
        return;
      }
      if (typeof event.topic === 'string' && typeof event.payload === 'string') {
        this.onEvent(event.topic, event.payload);
      }
    });
    socket.on('close', () => {
      if (this.socket === socket) {
        setTimeout(() => this.connect(), this.retryMs);
      }
    });
    socket.on('error', () => {
      socket.close();
    });
  }

  /** Hands one event to the gateway for broadcast to the watchers of topic; throws if topic is empty. */
  onEvent(topic: string, payload: string): void {
    if (!topic) {
      throw new Error('Event topic is required');
    }
    this.gateway.broadcast(topic, payload);
  }
}
