}

{
  "path": "src/live-updates/LiveGateway.ts",
  "content": "/**
 * WebSocket gateway for browsers that keeps watchers per item and broadcasts only to them.
 *
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private readonly outbox: Map<string, string[]> = new Map();

  constructor(public watchers: Map<string, Set<string>>) {}

  /** Registers a client as a watcher of an item; throws if either id is empty. */
  watch(clientId: string, itemId: string): void {
    if (!clientId || !itemId) {
      throw new Error('clientId and itemId are required');
    }
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set<string>();
      this.watchers.set(itemId, clients);
    }
    clients.add(clientId);
  }

  /** Removes a client from an item's watchers; drops the item when no watcher remains. */
  unwatch(clientId: string, itemId: string): void {
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    clients.delete(clientId);
    if (clients.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Queues a message for every client watching the item only; throws if the message is empty. */
  broadcast(itemId: string, message: string): void {
    if (!message) {
      throw new Error('message is required');
    }
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    for (const clientId of clients) {
      const queue = this.outbox.get(clientId) ?? [];
      queue.push(message);
      this.outbox.set(clientId, queue);
    }
  }
}
"
}

