 */
export class ItemController {
  constructor(private readonly itemService: ItemService) {}

  /** Validates a listing and creates an open auction; throws on missing fields or an unsupported currency. */
  async listItem(userId: string, title: string, startingPrice: number, endTime: string, currency: string): Promise<Item> {
    if (!userId) throw new Error('Seller id is required');
    if (!title) throw new Error('Title is required');
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice)) {
      throw new Error('Starting price is required');
    }
    if (!endTime) throw new Error('End time is required');
    if (!currency) throw new Error('Currency is required');
    if (!this.isCurrency(currency)) throw new Error(`Unsupported currency ${currency}`);
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) throw new Error('End time is invalid');
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /** Returns one item with its display-currency view; throws if the item is not found or the display currency is unsupported. */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    if (displayCurrency !== undefined && !this.isCurrency(displayCurrency)) {
      throw new Error(`Unsupported display currency ${displayCurrency}`);
    }
    const item = await this.itemService.getItem(id);
    return {
      item,
      displayCurrency: displayCurrency === undefined ? null : (displayCurrency as Currency),
      convertedStartingPrice: null,
      convertedHighestBid: null,
    };
  }

  /** Returns all auctions that are currently open for bids. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }

  /** Tells whether a value is one of the supported currencies. */
  private isCurrency(value: string): value is Currency {
