  "path": "src/auction-api/BidService.ts",
  "content": "import { randomUUID } from 'node:crypto';
import { Bid } from './Bid.js';
import { ItemStore } from './ItemStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';
import { UserStore } from './UserStore.js';

const LATE_BID_WINDOW_MS = 2 * 60 * 1000;
const MIN_INCREMENT = 1;

/**
 * Validates and stores bids, extends end time, and publishes accepted bids to the event feed.
 *
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Validates a bid on an open item, stores it, extends a late auction and publishes it; throws if the item is not found or the bid is invalid. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new Error('Bid amount must be a positive number');
    }
    const item = await this.itemStore.findItem(itemId);
    if (!item) {
      throw new Error(`Item ${itemId} not found`);
    }
    const now = new Date();
    const endTime = new Date(item.endTime);
    if (now.getTime() >= endTime.getTime()) {
      throw new Error('Auction has ended');
    }
    if (bidderId === item.sellerId) {
      throw new Error('Seller cannot bid on own item');
    }
    const highest = item.highestBidAmount ?? null;
    if (highest === null) {
      if (amount < item.startingPrice) {
        throw new Error(`First bid must be at least the starting price ${item.startingPrice}`);
      }
    } else if (amount < highest + MIN_INCREMENT) {
      throw new Error(`Bid must be at least ${MIN_INCREMENT} higher than the current highest bid ${highest}`);
    }

    const bid = new Bid(randomUUID(), item.id, bidderId, amount, now);
    await this.itemStore.saveBid(bid);

    item.highestBidAmount = amount;
    item.highestBidderId = bidderId;
    if (endTime.getTime() - now.getTime() <= LATE_BID_WINDOW_MS) {
      item.endTime = new Date(endTime.getTime() + LATE_BID_WINDOW_MS);
    }
    await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(bid, item);
    return bid;
  }
}
"
}

{
  "path": "src/exchange-rates/ExchangeRateService.ts",
  "content": "import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using rates cached for a configurable time; returns null when unavailable.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an amount between display currencies, returning null when no rate is available; throws on invalid amount or currency. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error(`Invalid amount ${amount}`);
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`Unsupported currency ${from}`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`Unsupported currency ${to}`);
    }
    if (from === to) {
      return amount;
    }
    const rates = await this.getRates(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number' || !Number.isFinite(rate)) {
      return null;
    }
    return amount * rate;
  }

  /** Returns cached rates for the base currency, fetching fresh ones when the cache is older than the TTL; returns null when unavailable. */
  private async getRates(base: Currency): Promise<Record<string, number> | null> {
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: now });
      return rates;
    } catch {
      return null;
    }
  }
}
"
}

