  "content": "import { DatabaseSync } from 'node:sqlite';
import { User } from './User.js';

/**
 * Persists users with a unique display name in the API server's SQLite database.
 *
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  private readonly database: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.database = db;
    this.database.exec(
      'CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, display_name TEXT NOT NULL UNIQUE)',
    );
  }

  /** Returns the user with the given display name, or null when none has it. */
  async findByName(displayName: string): Promise<User | null> {
    const row = this.database
      .prepare('SELECT id, display_name FROM users WHERE display_name = ?')
      .get(displayName) as unknown as { id: string; display_name: string } | undefined;
    return row ? new User(row.id, row.display_name) : null;
  }

  /** Inserts or updates the user; throws if the display name is invalid or taken by another user. */
  async save(user: User): Promise<User> {
    const length = user.displayName.length;
    if (length < 2 || length > 20) {
      throw new Error('Display name must be 2 to 20 characters');
    }
    const sameName = this.database
      .prepare('SELECT id FROM users WHERE display_name = ?')
      .get(user.displayName) as unknown as { id: string } | undefined;
    if (sameName && sameName.id !== user.id) {
      throw new Error(`Display name ${user.displayName} already taken`);
    }
    const sameId = this.database
      .prepare('SELECT id FROM users WHERE id = ?')
      .get(user.id) as unknown as { id: string } | undefined;
    if (sameId) {
      this.database
        .prepare('UPDATE users SET display_name = ? WHERE id = ?')
        .run(user.displayName, user.id);
    } else {
      this.database
        .prepare('INSERT INTO users (id, display_name) VALUES (?, ?)')
        .run(user.id, user.displayName);
    }
    return user;
  }
}
"
}

{
  "path": "src/exchange-rates/FrankfurterClient.ts",
  "content": "import { Currency } from '../auction-api/Currency.js';

const API_URL = 'https://api.frankfurter.app/latest';
const CACHE_TTL_MS = 60 * 60 * 1000;

interface CacheEntry {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Fetches display exchange rates from the Frankfurter API with a one hour cache.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private readonly cache = new Map<string, CacheEntry>();

  constructor() {}

  /** Returns rates for the base currency, using the cache for one hour; returns an empty record when the API is unreachable and no cached rate is valid. Throws if the base currency is unsupported. */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    if (!Object.values(Currency).includes(base)) {
      throw new Error(`Unsupported currency ${String(base)}`);
    }
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
      return { ...cached.rates };
    }
    try {
      const rates = await this.request(base);
      this.cache.set(base, { rates, fetchedAt: Date.now() });
      return { ...rates };
    } catch {
      if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
        return { ...cached.rates };
      }
      return {};
    }
  }

  /** Performs the HTTPS request and returns the rate map; throws on network or response errors. */
  private async request(base: Currency): Promise<Record<string, number>> {
    const url = `${API_URL}?from=${base}&to=${Object.values(Currency).join(',')}`;
    const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
    if (!response.ok) {
      throw new Error(`Frankfurter responded with status ${response.status}`);
    }
    const body = (await response.json()) as { rates?: Record<string, unknown> };
    if (!body.rates || typeof body.rates !== 'object') {
      throw new Error('Frankfurter response has no rates');
    }
    const rates: Record<string, number> = {};
    for (const [code, value] of Object.entries(body.rates)) {
      if (typeof value === 'number') {
        rates[code] = value;
      }
    }
    return rates;
  }
}
"
