  console.log(`API server listening on port ${port}`);
});

const feed = app.locals.eventFeed as EventFeed;
server.on('upgrade', (request, socket, head) => {
  if (request.url === '/internal/live-update-server') {
    EventFeed.accept(feed, request, socket, head);
  } else {
    socket.destroy();
  }
});

const closer = app.locals.auctionCloser as AuctionCloser;
setInterval(() => {
  closer.tick().catch((err) => console.error(err));
}, closer.intervalMs);

