import express from 'express';
import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import { WebSocket, WebSocketServer } from 'ws';
import { LiveGateway } from '../live-updates/LiveGateway.js';
import { EventFeedClient } from '../live-updates/EventFeedClient.js';

const gateway = new LiveGateway(new Map<string, Set<string>>());
const sockets = new Map<string, WebSocket>();

const apiUrl = `${process.env.API_SERVER_OWNS_SQ_LITE_URL ?? 'ws://localhost:8080'}/internal/live-update-server`;
const feedClient = new EventFeedClient(apiUrl);

// Deliver each feed event to the sockets of the clients watching its item.
const handleEvent = feedClient.onEvent.bind(feedClient);
feedClient.onEvent = (topic: string, payload: string): void => {
  handleEvent(topic, payload);
  const itemId = topic.replace(/^item:/, '').replace(/^auction\.closed\./, '');
  const message = JSON.stringify({ topic, itemId, payload });
  for (const clientId of gateway.watchers.get(itemId) ?? []) {
    const socket = sockets.get(clientId);
    if (socket && socket.readyState === WebSocket.OPEN) socket.send(message);
  }
};

const app = express();
app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

const server = createServer(app);
const wss = new WebSocketServer({ server });
wss.on('connection', (socket) => {
  const clientId = randomUUID();
  sockets.set(clientId, socket);
  socket.on('message', (data) => {
    try {
      const msg = JSON.parse(data.toString()) as { action?: string; itemId?: string };
      if (typeof msg.itemId !== 'string') return;
      if (msg.action === 'watch') gateway.watch(clientId, msg.itemId);
      else if (msg.action === 'unwatch') gateway.unwatch(clientId, msg.itemId);
    } catch {
      // ignore malformed messages
    }
  });
  socket.on('close', () => {
    sockets.delete(clientId);
    for (const [itemId, clients] of [...gateway.watchers]) {
      if (clients.has(clientId)) gateway.unwatch(clientId, itemId);
    }
  });
});

const port = Number(process.env.LIVE_UPDATE_SERVER_PORT ?? 8081);
server.listen(port, () => {
  console.log(`Live update server listening on port ${port}`);
});
feedClient.connect();

